#!/bin/sh
# ============================================================================
# build-a27-boot.sh — build the A27 BOOT candidate (seamless first light).
#
# A27 = A25 (hardware-proven, currently on the handset) with ONE user-visible
# change and the delivery audit the mission asks for:
#
#   1. opt/nuxel/nuxel-fb-phone  rebuilt with the NUXSPL01 renderer, so the
#      earliest lit frame IS frame 0 of the original animation (asset below);
#   2. opt/nuxel/nuxel-firstlight.rawspl  1.9 MB, uncompressed, generated by
#      tools/s10plus/a26/make-firstlight-asset.py from build/out/s10plus/
#      nuxel-animation.nux (NUXANM01), i.e. from the ORIGINAL MP4-derived artwork;
#   3. /init (boot/initramfs/init.sh): passes the asset to the painter, logs its
#      presence, and no longer lets a BOOT candidate overwrite a UI that was
#      DEPLOYED LIVE (the /usr/lib/nuxel/ui.pinned rule), so this flash cannot
#      replace newer, proven Fedora userspace;
#   4. everything else is byte-identical to the A25 archive that boots today.
#
# The release gate is FAIL-CLOSED on the thing that actually matters: the ARM64
# binary must CONTAIN the renderer (a string in a comment is not an
# implementation), the asset must parse and render byte-identically to the
# player's own frame 0 (tools/s10plus/a27/test-firstlight.sh), and the packed
# container must pass tools/s10plus/verify-a25-boot.py.
#
# Usage:
#   sh tools/s10plus/a27/build-a27-boot.sh                  # initramfs + boot.img
#   NUXEL_A27_KERNEL=1 sh .../build-a27-boot.sh             # also rebuild Image
# Exit: 0 ok, 1 a gate failed, 2 a required input is missing.
# ============================================================================
set -eu
ROOT=$(cd "$(dirname "$0")/../../.." && pwd)
CAND=${CAND:-A27}
A25DIR="$ROOT/build/out/s10plus/debug-candidates/A25"
OUT="$ROOT/build/out/s10plus/debug-candidates/$CAND"
NEWC="$ROOT/tools/s10plus/newc.py"
CC=${NUXEL_AARCH64_CC:-aarch64-linux-gnu-gcc}
PLAYER="$ROOT/build/out/s10plus/nuxel-anim-player"
ASSET_RAW="$ROOT/build/out/s10plus/a27/nuxel-firstlight.rawspl"
PARTITION_BYTES=${NUXEL_BOOT_PARTITION_BYTES:-57671680}
mkdir -p "$OUT" "$ROOT/build/out/s10plus/a27"
sha() { shasum -a 256 "$1" | cut -d' ' -f1; }
say() { printf '[a27] %s\n' "$*"; }
die() { printf '[a27][FAIL] %s\n' "$*" >&2; exit 1; }

[ -s "$A25DIR/initramfs.cpio" ] || die "missing A25 base initramfs (the archive the handset runs)"
[ -s "$A25DIR/boot.img" ] || die "missing A25 base boot.img (source of the proven DTB)"

# ---------------------------------------------------------------------------
# 1. the ARM64 first-light painter
# ---------------------------------------------------------------------------
say "1. compiling the freestanding ARM64 first-light painter"
"$CC" -Os -w -ffreestanding -fno-builtin -nostdlib -static -s -Wl,--build-id=none \
      -o "$ROOT/build/out/s10plus/nuxel-fb-phone" "$ROOT/tools/s10plus/nuxel-fb-phone.c" \
      || die "nuxel-fb-phone.c did not compile"
FBPHONE="$ROOT/build/out/s10plus/nuxel-fb-phone"
file -b "$FBPHONE" | grep -q aarch64 || die "$FBPHONE is not an ARM64 ELF"
# THE GATE: the implementation must be IN THE BINARY.  A comment mentioning
# --firstlight proves nothing, and a stale binary must never ship: the builder
# fails with a nonzero exit code if the renderer is absent.
if ! strings -a "$FBPHONE" | grep -q "NUXEL_FIRSTLIGHT_FRAME0_PAINTED"; then
    die "the ARM64 binary carries no NUXSPL01 renderer (stale/partial build) — refusing to build a candidate that would still paint the old splash"
fi
if ! strings -a "$FBPHONE" | grep -q "NUXEL_FIRSTLIGHT_REJECTED="; then
    die "the ARM64 binary has no named rejection path for a malformed asset"
fi
say "   ok  $(basename "$FBPHONE") $(wc -c <"$FBPHONE" | tr -d ' ') bytes $(sha "$FBPHONE" | cut -c1-16)…"

# ---------------------------------------------------------------------------
# 2. the first-light asset, regenerated from the ORIGINAL container
# ---------------------------------------------------------------------------
say "2. regenerating the NUXSPL01 asset from nuxel-animation.nux (NUXANM01)"
python3 "$ROOT/tools/s10plus/a26/make-firstlight-asset.py" \
    --anim "$ROOT/build/out/s10plus/nuxel-animation.nux" \
    --out "$ROOT/build/out/s10plus/a26/nuxel-firstlight.nuxspl" \
    --raw-out "$ASSET_RAW" \
    --mp4 "$ROOT/assets/nuxel-boot-animation.mp4" \
    --report "$ROOT/build/out/s10plus/a27/nuxel-firstlight.report.json" | tail -3
[ -s "$ASSET_RAW" ] || die "no raw first-light asset produced"

# ---------------------------------------------------------------------------
# 3. off-device proof that the early frame IS the player's frame 0
# ---------------------------------------------------------------------------
say "3. first-light gate (renderer vs reference, malformed-asset rejection)"
sh "$ROOT/tools/s10plus/a27/test-firstlight.sh" "$ASSET_RAW" >"$ROOT/build/out/s10plus/a27/tests.log" 2>&1 \
    || { tail -20 "$ROOT/build/out/s10plus/a27/tests.log"; die "test-firstlight.sh failed"; }
grep -q A27_FIRSTLIGHT_TESTS_OK "$ROOT/build/out/s10plus/a27/tests.log" || die "first-light tests did not pass"
say "   ok  $(grep -c '   PASS' "$ROOT/build/out/s10plus/a27/tests.log") checks passed"

# ---------------------------------------------------------------------------
# 4. the initramfs: A25 + exactly these members
# ---------------------------------------------------------------------------
say "4. assembling the A27 initramfs from the A25 archive"
STAGE="$OUT/initramfs.cpio"
cp -f "$A25DIR/initramfs.cpio" "$STAGE"
python3 "$NEWC" replace "$STAGE" init "$ROOT/boot/initramfs/init.sh" "$STAGE.t" --mode=0100755 && mv -f "$STAGE.t" "$STAGE"
python3 "$NEWC" replace "$STAGE" opt/nuxel/nuxel-fb-phone "$FBPHONE" "$STAGE.t" --mode=0100755 && mv -f "$STAGE.t" "$STAGE"
python3 "$NEWC" insert "$STAGE" "$STAGE.t" --after opt/nuxel/nuxel-anim-player \
        --name opt/nuxel/nuxel-firstlight.rawspl --mode 0100644 --type file --file "$ASSET_RAW" \
    && mv -f "$STAGE.t" "$STAGE"
for pair in "init:$ROOT/boot/initramfs/init.sh" \
            "opt/nuxel/nuxel-fb-phone:$FBPHONE" \
            "opt/nuxel/nuxel-firstlight.rawspl:$ASSET_RAW"; do
    name=${pair%%:*}; src=${pair#*:}
    python3 "$NEWC" extract "$STAGE" "$name" "$OUT/verify.tmp"
    a=$(sha "$OUT/verify.tmp"); b=$(sha "$src")
    [ "$a" = "$b" ] && say "   OK   $name  ${a%${a#????????????????}}" \
                    || die "member $name does not match its source"
done
rm -f "$OUT/verify.tmp"

# the members the A25 archive already carries must still be there, unchanged in
# kind: the delivery set the verifier checks.
for m in opt/nuxel/nuxel-ui opt/nuxel/nuxel-console opt/nuxel/nuxel-anim-player \
         opt/nuxel/nuxel-postboot.sh opt/nuxel/nuxel-ui.service opt/nuxel/nuxel-ui.rev \
         opt/nuxel/libsystemd-shared-258.11-1.fc43.so bin/toybox; do
    python3 "$NEWC" list "$STAGE" | grep -q " $m\$" || die "A25 member missing from the A27 archive: $m"
done
say "   ok  initramfs $(wc -c <"$STAGE" | tr -d ' ') bytes sha256 $(sha "$STAGE" | cut -c1-16)…"

# ---------------------------------------------------------------------------
# 5. kernel Image with the A27 initramfs embedded (podman: nuxel-kb)
# ---------------------------------------------------------------------------
if [ "${NUXEL_A27_KERNEL:-0}" = 1 ]; then
    say "5. rebuilding Image in the nuxel-kb container (initramfs embedded)"
    timeout 120 podman start nuxel-kb >/dev/null
    podman exec nuxel-kb mkdir -p /b/a27
    podman cp "$STAGE" nuxel-kb:/b/a27/initramfs-a27.cpio
    podman cp "$ROOT/tools/s10plus/a27/kbuild-a27.sh" nuxel-kb:/b/a27/kbuild-a27.sh
    podman exec nuxel-kb sh /b/a27/kbuild-a27.sh
    podman exec nuxel-kb cat /b/a27/build-a27.log
    podman cp nuxel-kb:/b/a27/Image-A27 "$OUT/Image-A27"
    [ -s "$OUT/Image-A27" ] || die "container produced no Image"
    say "   ok  Image-A27 $(wc -c <"$OUT/Image-A27" | tr -d ' ') bytes"
else
    say "5. kernel rebuild skipped (NUXEL_A27_KERNEL=1 to rebuild)"
fi

# ---------------------------------------------------------------------------
# 6. BOOT container (legacy v1 header, page 2048) — same structure as A25
# ---------------------------------------------------------------------------
[ -s "$OUT/Image-A27" ] || die "no Image-A27 to pack (run with NUXEL_A27_KERNEL=1)"
say "6. packing the BOOT container"
# the ramdisk copy is lzma-alone with the 64 KiB zero padding the hardware ran
# with; only non-S-Boot consumers read it (S-Boot uses the kernel's embedded
# initramfs), so it stays byte-for-byte the proven recipe.
python3 - "$STAGE" "$OUT/initramfs-A27.ramdisk.lzma" <<'PY'
import lzma, sys
cpio, out = sys.argv[1], sys.argv[2]
data = open(cpio, "rb").read() + b"\x00" * 65536
blob = lzma.compress(data, format=lzma.FORMAT_ALONE,
                     filters=[{"id": lzma.FILTER_LZMA1, "preset": 6, "dict_size": 1 << 23}])
pad = (-len(blob)) % 65536
open(out, "wb").write(blob + b"\x00" * pad)
print("  ramdisk lzma: %d bytes (payload %d, pad %d)" % (len(blob) + pad, len(blob), pad))
PY
# The DTB is taken VERBATIM from the A25 container the handset boots: the device
# tree is untouched by this change, so re-deriving it could only introduce a
# difference for no reason.
python3 - "$A25DIR/boot.img" "$OUT/exynos9820-beyond2lte.dtb" <<'PY'
import struct, sys
src, out = sys.argv[1], sys.argv[2]
d = open(src, "rb").read()
ks, ka, rs, ra, ss, sa, ta, ps, dt, osv = struct.unpack_from("<10I", d, 8)
off = ps + ((ks + ps - 1) // ps) * ps + ((rs + ps - 1) // ps) * ps
open(out, "wb").write(d[off:off + dt])
print("  dtb from A25 container: offset %d size %d" % (off, dt))
PY
python3 "$ROOT/boot/s10plus/pack-boot-v1.sh" \
    --kernel  "$OUT/Image-A27" \
    --ramdisk "$OUT/initramfs-A27.ramdisk.lzma" \
    --dtb     "$OUT/exynos9820-beyond2lte.dtb" \
    --cmdline "buildvariant=userdebug nuxel.device=s10plus root=/dev/block/platform/13d60000.ufs/by-name/userdata rootfstype=ext4 rootwait rw" \
    --kernel-addr 0x10008000 --ramdisk-addr 0x11000000 --tags-addr 0x10000100 \
    --v1-spec --strict --output "$OUT/boot.img"

# ---------------------------------------------------------------------------
# 7. fail-closed release gate
# ---------------------------------------------------------------------------
say "7. release gate (verify-a25-boot.py)"
python3 "$ROOT/tools/s10plus/verify-a25-boot.py" \
    --boot-image "$OUT/boot.img" \
    --kernel "$OUT/Image-A27" \
    --initramfs "$STAGE" \
    --partition-bytes "$PARTITION_BYTES" \
    --report "$OUT/boot.report.txt" || die "the BOOT candidate failed verification"

BOOTSHA=$(sha "$OUT/boot.img"); IMSHA=$(sha "$OUT/Image-A27"); CPSHA=$(sha "$STAGE")
{
  echo "candidate=$CAND"
  echo "purpose=seamless original-animation first light (NUXSPL01 = MP4-derived frame 0)"
  echo "base_initramfs=$A25DIR/initramfs.cpio sha256=$(sha "$A25DIR/initramfs.cpio")"
  echo "boot_img=$OUT/boot.img bytes=$(wc -c <"$OUT/boot.img" | tr -d ' ') sha256=$BOOTSHA"
  echo "kernel=$OUT/Image-A27 bytes=$(wc -c <"$OUT/Image-A27" | tr -d ' ') sha256=$IMSHA"
  echo "initramfs=$STAGE bytes=$(wc -c <"$STAGE" | tr -d ' ') sha256=$CPSHA"
  echo "nuxel_fb_phone sha256=$(sha "$FBPHONE")"
  echo "firstlight_asset=$ASSET_RAW bytes=$(wc -c <"$ASSET_RAW" | tr -d ' ') sha256=$(sha "$ASSET_RAW")"
  echo "partition_bytes=$PARTITION_BYTES"
  echo "flashed=false"
} > "$OUT/CANDIDATE.txt"
cat "$OUT/CANDIDATE.txt"
say "A27_BOOT_CANDIDATE_READY $OUT/boot.img"
